import * as React from 'react';
import type { NavigationItem } from '../data/dashboardData';

export interface SidebarProps {
  items: NavigationItem[];
  selectedItemId: string;
  onSelect: (itemId: string) => void;
}

const baseButtonClasses =
  'group flex min-w-0 items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-medium transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2 focus-visible:ring-offset-slate-950 sm:flex-1 lg:flex-none';

const activeButtonClasses =
  'bg-indigo-600 text-white shadow-sm hover:bg-indigo-500';

const inactiveButtonClasses =
  'text-slate-300 hover:bg-slate-800 hover:text-white';

const badgeBaseClasses =
  'inline-flex min-w-6 items-center justify-center rounded-full px-2 py-0.5 text-xs font-semibold';

const getItemMonogram = (item: NavigationItem): string => {
  const source = item.icon?.trim() || item.label.trim();
  return source.slice(0, 2).toUpperCase();
};

export function Sidebar({
  items,
  selectedItemId,
  onSelect,
}: SidebarProps): React.JSX.Element {
  const handleSelect = React.useCallback(
    (itemId: string) => {
      onSelect(itemId);
    },
    [onSelect],
  );

  return (
    <aside className="w-full border-b border-slate-800 bg-slate-950 text-slate-100 lg:min-h-screen lg:w-72 lg:border-b-0 lg:border-r">
      <div className="flex flex-col gap-4 px-4 py-4 sm:px-5 lg:sticky lg:top-0 lg:h-screen lg:px-6 lg:py-6">
        <div className="flex items-center justify-between gap-3 lg:flex-col lg:items-start lg:justify-start">
          <div className="min-w-0">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-indigo-600/20 text-lg font-bold text-indigo-300 ring-1 ring-inset ring-indigo-500/30">
                DS
              </div>
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold tracking-wide text-white">
                  DataScope
                </p>
                <p className="truncate text-xs text-slate-400">
                  Executive Dashboard
                </p>
              </div>
            </div>
          </div>

          <div className="hidden rounded-full border border-slate-800 bg-slate-900 px-3 py-1 text-xs font-medium text-slate-300 sm:inline-flex lg:hidden">
            Navigation
          </div>
        </div>

        <nav
          aria-label="Primary navigation"
          className="overflow-x-auto pb-1 lg:flex-1 lg:overflow-x-visible lg:pb-0"
        >
          <div className="flex min-w-max gap-2 lg:min-w-0 lg:flex-col">
            {items.map((item) => {
              const isActive = item.id === selectedItemId;

              return (
                <button
                  key={item.id}
                  type="button"
                  aria-pressed={isActive}
                  aria-current={isActive ? 'page' : undefined}
                  onClick={() => handleSelect(item.id)}
                  className={`${baseButtonClasses} ${
                    isActive ? activeButtonClasses : inactiveButtonClasses
                  }`}
                  title={item.label}
                >
                  <span
                    aria-hidden="true"
                    className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-xs font-bold uppercase transition-colors ${
                      isActive
                        ? 'bg-white/15 text-white'
                        : 'bg-slate-800 text-slate-300 group-hover:bg-slate-700 group-hover:text-white'
                    }`}
                  >
                    {getItemMonogram(item)}
                  </span>

                  <span className="flex min-w-0 flex-1 items-center gap-2 lg:gap-3">
                    <span className="min-w-0 flex-1">
                      <span className="block truncate">{item.label}</span>
                      {item.description ? (
                        <span
                          className={`mt-0.5 hidden truncate text-xs lg:block ${
                            isActive ? 'text-indigo-100/90' : 'text-slate-400'
                          }`}
                        >
                          {item.description}
                        </span>
                      ) : null}
                    </span>

                    {typeof item.badgeCount === 'number' ? (
                      <span
                        className={`${badgeBaseClasses} ${
                          isActive
                            ? 'bg-white/15 text-white'
                            : 'bg-slate-800 text-slate-200 group-hover:bg-slate-700'
                        }`}
                        aria-label={`${item.badgeCount} notifications`}
                      >
                        {item.badgeCount}
                      </span>
                    ) : null}
                  </span>
                </button>
              );
            })}
          </div>
        </nav>
      </div>
    </aside>
  );
}

export default Sidebar;

import React from 'react';

