        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '1rem',
        padding: '1.25rem 1.5rem',
        borderRadius: '1rem',
        background:
          'linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.92))',
        color: '#f8fafc',
        boxShadow: '0 12px 30px rgba(15, 23, 42, 0.18)',
