import React, { useMemo } from 'react';
import type { Metric } from '../data/dashboardData';

interface MetricCardsProps {
  metrics?: Array<Partial<Metric>>;
}

const containerStyle: React.CSSProperties = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
  gap: '1rem',
  width: '100%',
};

const cardStyle: React.CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: '0.5rem',
  padding: '1rem',
  borderRadius: '16px',
  border: '1px solid rgba(148, 163, 184, 0.2)',
  background: 'linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)',
  boxShadow: '0 10px 30px rgba(15, 23, 42, 0.08)',
  minHeight: '140px',
};

const titleStyle: React.CSSProperties = {
  margin: 0,
  fontSize: '0.95rem',
  fontWeight: 600,
  color: '#475569',
};

const valueStyle: React.CSSProperties = {
  margin: 0,
  fontSize: '1.9rem',
  lineHeight: 1.1,
  fontWeight: 700,
  color: '#0f172a',
};

const changeBaseStyle: React.CSSProperties = {
  margin: 0,
  fontSize: '0.95rem',
  fontWeight: 600,
};

const emptyStateStyle: React.CSSProperties = {
  width: '100%',
  padding: '1.5rem',
  borderRadius: '16px',
  border: '1px dashed rgba(148, 163, 184, 0.5)',
  backgroundColor: '#f8fafc',
  color: '#475569',
  textAlign: 'center',
  fontSize: '1rem',
  fontWeight: 600,
};

const getChangeColor = (trendDirection?: Metric['trendDirection']): string => {
  if (trendDirection === 'up') {
    return '#059669';
  }

  if (trendDirection === 'down') {
    return '#dc2626';
  }

  return '#64748b';
};

export function MetricCards({ metrics }: MetricCardsProps): React.JSX.Element {
  const safeMetrics = useMemo(() => {
    if (!Array.isArray(metrics) || metrics.length === 0) {
      return [];
    }

    return metrics.map((metric, index) => ({
      id: metric.id ?? `metric-${index}`,
      label: metric.label?.trim() ? metric.label : 'Untitled metric',
      value: metric.value?.trim() ? metric.value : '--',
      change: metric.change?.trim() ? metric.change : 'No change data',
      trendDirection: metric.trendDirection ?? 'neutral',
    }));
  }, [metrics]);

  if (safeMetrics.length === 0) {
    return <div style={emptyStateStyle}>No metrics available</div>;
  }

  return (
    <div style={containerStyle}>
      {safeMetrics.map((metric) => (
        <article key={metric.id} style={cardStyle} aria-label={metric.label}>
          <h3 style={titleStyle}>{metric.label}</h3>
          <p style={valueStyle}>{metric.value}</p>
          <p
            style={{
              ...changeBaseStyle,
              color: getChangeColor(metric.trendDirection),
            }}
          >
            {metric.change}
          </p>
        </article>
      ))}
    </div>
  );
}

export default MetricCards;

import * as React from 'react';
import type { CSSProperties, ReactNode } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import type { CategoryChartData, TrendPoint } from '../data/dashboardData';

/** Props for the ChartsSection component. */
export interface ChartsSectionProps {
  /** Seven-day trend data used by the line chart. */
  trendData?: TrendPoint[];
  /** Category distribution data used by the secondary chart. */
  categoryData?: CategoryChartData[];
}

interface ChartCardProps {
  title: string;
  subtitle: string;
  children: ReactNode;
}

interface PlaceholderCardProps {
  message: string;
}

interface SafeTrendDatum {
  label: string;
  value: number;
  secondaryValue: number;
  annotation: string;
}

interface SafeCategoryDatum {
  id: string;
  label: string;
  value: number;
  color: string;
  percentage: number;
  detail: string;
}

const sectionStyle: CSSProperties = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
  gap: '1.5rem',
  width: '100%',
};

const cardStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: '1rem',
  minHeight: '360px',
  padding: '1.25rem',
  borderRadius: '20px',
  border: '1px solid #e2e8f0',
  backgroundColor: '#ffffff',
  boxShadow: '0 10px 30px rgba(15, 23, 42, 0.06)',
};

const headerStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: '0.35rem',
};

const titleStyle: CSSProperties = {
  margin: 0,
  fontSize: '1.1rem',
  fontWeight: 700,
  color: '#0f172a',
};

const subtitleStyle: CSSProperties = {
  margin: 0,
  fontSize: '0.95rem',
  color: '#64748b',
  lineHeight: 1.5,
};

const chartWrapperStyle: CSSProperties = {
  width: '100%',
  minHeight: '280px',
  height: '280px',
  flex: 1,
};

const placeholderStyle: CSSProperties = {
  minHeight: '280px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  textAlign: 'center',
  padding: '1.5rem',
  borderRadius: '16px',
  border: '1px dashed #cbd5e1',
  backgroundColor: '#f8fafc',
  color: '#64748b',
  lineHeight: 1.6,
};

const tooltipContentStyle: CSSProperties = {
  borderRadius: '12px',
  border: '1px solid #cbd5e1',
  boxShadow: '0 10px 25px rgba(15, 23, 42, 0.12)',
  backgroundColor: '#ffffff',
};

const legendWrapperStyle: CSSProperties = {
  fontSize: '0.85rem',
  paddingTop: '0.5rem',
};

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function formatTooltipValue(value: unknown): number {
  if (isFiniteNumber(value)) {
    return value;
  }

  const parsedValue: number = Number(value ?? 0);
  return Number.isFinite(parsedValue) ? parsedValue : 0;
}

function buildSafeTrendData(data?: TrendPoint[]): SafeTrendDatum[] {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  return data.slice(0, 7).map((point: TrendPoint, index: number) => ({
    label: point?.label ?? `Day ${index + 1}`,
    value: isFiniteNumber(point?.value) ? point.value : 0,
    secondaryValue: isFiniteNumber(point?.secondaryValue) ? point.secondaryValue : 0,
    annotation: point?.annotation ?? '',
  }));
}

function buildSafeCategoryData(data?: CategoryChartData[]): SafeCategoryDatum[] {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  return data.map((item: CategoryChartData, index: number) => ({
    id: item?.id ?? `category-${index}`,
    label: item?.label ?? `Category ${index + 1}`,
    value: isFiniteNumber(item?.value) ? item.value : 0,
    color: item?.color ?? '#94a3b8',
    percentage: isFiniteNumber(item?.percentage) ? item.percentage : 0,
    detail: item?.detail ?? '',
  }));
}

function ChartCard({ title, subtitle, children }: ChartCardProps): React.JSX.Element {
  return (
    <article style={cardStyle}>
      <header style={headerStyle}>
        <h3 style={titleStyle}>{title}</h3>
        <p style={subtitleStyle}>{subtitle}</p>
      </header>
      {children}
    </article>
  );
}

function PlaceholderCard({ message }: PlaceholderCardProps): React.JSX.Element {
  return <div style={placeholderStyle}>{message}</div>;
}

/**
 * Renders two responsive dashboard charts with defensive fallbacks for missing datasets.
 */
export default function ChartsSection({
  trendData,
  categoryData,
}: ChartsSectionProps): React.JSX.Element {
  const safeTrendData: SafeTrendDatum[] = React.useMemo(() => buildSafeTrendData(trendData), [trendData]);
  const safeCategoryData: SafeCategoryDatum[] = React.useMemo(
    () => buildSafeCategoryData(categoryData),
    [categoryData],
  );

  const hasTrendData: boolean = safeTrendData.length > 0;
  const hasCategoryData: boolean = safeCategoryData.length > 0;

  return (
    <section style={sectionStyle} aria-label="Charts overview section">
      <ChartCard
        title="7-Day Performance Trend"
        subtitle="Primary and secondary values across the latest seven-day period"
      >
        {hasTrendData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={safeTrendData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown): [string | number, string] => {
                    const numericValue: number = formatTooltipValue(value);
                    const safeName: string = typeof name === 'string' ? name : 'Value';
                    const payload: SafeTrendDatum | undefined =
                      item !== null && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeTrendDatum }).payload
                        : undefined;
                    const annotation: string = payload?.annotation ?? '';

                    return annotation
                      ? [`${numericValue} (${annotation})`, safeName]
                      : [numericValue, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Line
                  type="monotone"
                  dataKey="value"
                  name="Primary"
