          </div>
        ) : (
          <PlaceholderCard message="Trend data is unavailable right now. Add a seven-day dataset to display the line chart." />
        )}
      </ChartCard>

      <ChartCard
        title="Category Distribution"
        subtitle="Segment totals shown as a responsive bar chart with legend and axes"
      >
        {hasCategoryData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={safeCategoryData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown): [string | number, string] => {
                    const numericValue: number = formatTooltipValue(value);
                    const safeName: string = typeof name === 'string' ? name : 'Value';
                    const payload: SafeCategoryDatum | undefined =
                      item !== null && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeCategoryDatum }).payload
                        : undefined;
                    const percentageSuffix: string = payload?.percentage
                      ? ` (${payload.percentage}%)`
                      : '';
                    const detailSuffix: string = payload?.detail ? ` — ${payload.detail}` : '';

                    return [`${numericValue}${percentageSuffix}${detailSuffix}`, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Bar dataKey="value" name="Value" radius={[8, 8, 0, 0]}>
                  {safeCategoryData.map((entry: SafeCategoryDatum) => (
                    <Cell key={entry.id} fill={entry.color ?? '#94a3b8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Category data is unavailable right now. Add distribution data to display the chart." />
        )}
      </ChartCard>
    </section>
  );
}

