const FALLBACK_TITLE = 'Untitled activity';
const FALLBACK_DETAIL = 'Status unavailable';
const FALLBACK_TIME = 'Time unavailable';

const formatTimestamp = (timestamp?: string): string => {
  if (!timestamp) {
    return FALLBACK_TIME;
  }

  const date = new Date(timestamp);

  if (Number.isNaN(date.getTime())) {
    return FALLBACK_TIME;
  }

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(date);
};

const getTimestampValue = (timestamp?: string): number => {
  if (!timestamp) {
    return Number.NEGATIVE_INFINITY;
  }

  const timeValue = new Date(timestamp).getTime();
  return Number.isNaN(timeValue) ? Number.NEGATIVE_INFINITY : timeValue;
};

const getActivityDetail = (item: Partial<ActivityItem>): string => {
  const description = typeof item.description === 'string' ? item.description.trim() : '';
  if (description) {
    return description;
  }

  const status = typeof item.status === 'string' ? item.status.replace(/-/g, ' ').trim() : '';
  if (status) {
    return status.charAt(0).toUpperCase() + status.slice(1);
  }

  return FALLBACK_DETAIL;
};

const RecentActivity = ({ items }: RecentActivityProps): React.JSX.Element => {
  const sortedItems = useMemo(() => {
    if (!Array.isArray(items)) {
      return [];
    }

    return [...items].sort((firstItem, secondItem) => {
      return getTimestampValue(secondItem?.timestamp) - getTimestampValue(firstItem?.timestamp);
    });
  }, [items]);

  if (sortedItems.length === 0) {
    return (
      <section style={containerStyle} aria-live="polite">
        <p style={emptyStateStyle}>No recent activity</p>
      </section>
    );
  }

  return (
    <section style={containerStyle} aria-label="Recent activity">
      <ul style={listStyle}>
        {sortedItems.map((item, index) => {
          const safeTitle = typeof item?.title === 'string' && item.title.trim() ? item.title : FALLBACK_TITLE;
          const safeTime = formatTimestamp(item?.timestamp);
          const detail = getActivityDetail(item ?? {});
          const statusLabel = typeof item?.status === 'string' && item.status.trim()
            ? item.status.replace(/-/g, ' ')
            : undefined;
          const key = typeof item?.id === 'string' && item.id.trim() ? item.id : `activity-${index}`;

          return (
            <li key={key} style={itemStyle}>
              <div style={headerRowStyle}>
                <h3 style={titleStyle}>{safeTitle}</h3>
                <time style={timeStyle} dateTime={typeof item?.timestamp === 'string' ? item.timestamp : undefined}>
                  {safeTime}
                </time>
              </div>

              <p style={detailStyle}>{detail}</p>

              {(statusLabel || item?.category || item?.userName) && (
                <div style={metaStyle}>
                  {statusLabel && <span style={badgeStyle}>{statusLabel}</span>}
                  {item?.category && <span>{item.category}</span>}
                  {item?.userName && <span>{item.userName}</span>}
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
};

export default RecentActivity;

import * as React from 'react';

/** Props for the DashboardLayout component. */
export interface DashboardLayoutProps {
  /** Sidebar content rendered alongside the main dashboard area on desktop screens. */
  sidebar: React.ReactNode;
  /** Optional header content rendered at the top of the main content column. */
  header?: React.ReactNode;
  /** Metrics content rendered first inside the main content area. */
  metrics: React.ReactNode;
  /** Charts content rendered in the responsive secondary grid. */
  charts: React.ReactNode;
  /** Activity content rendered beside charts on larger screens and below on smaller screens. */
  activity: React.ReactNode;
  /** Optional additional class name for the outermost layout container. */
  className?: string;
}

const getContainerClasses = (className?: string): string => {
  const baseClasses = [
    'min-h-screen',
    'w-full',
    'overflow-x-hidden',
    'bg-slate-100',
    'text-slate-900',
    'lg:flex',
    'lg:items-stretch',
  ];

  if (typeof className === 'string' && className.trim()) {
    baseClasses.push(className.trim());
  }

  return baseClasses.join(' ');
};

/**
 * Provides a responsive dashboard shell with a sidebar and main content area.
 *
 * The main content is ordered as header, metrics, then a responsive charts/activity
 * grid that collapses to a single column on smaller screens while preserving
 * min-width safeguards to prevent horizontal overflow.
 */
export function DashboardLayout({
  sidebar,
  header,
  metrics,
  charts,
  activity,
  className,
}: DashboardLayoutProps): React.JSX.Element {
  return (
    <div className={getContainerClasses(className)}>
      <div className="min-w-0 shrink-0 lg:w-72 lg:max-w-[18rem] lg:basis-72">
        {sidebar}
      </div>

      <main className="min-w-0 flex-1 overflow-x-hidden">
        <div className="mx-auto flex min-w-0 w-full max-w-screen-2xl flex-col gap-6 px-4 py-4 sm:gap-6 sm:px-6 sm:py-6 lg:px-8 lg:py-8 xl:px-10">
          {header ? <div className="min-w-0">{header}</div> : null}

          <section className="min-w-0" aria-label="Dashboard metrics">
            {metrics}
          </section>

          <section
            className="grid min-w-0 grid-cols-1 gap-6 xl:grid-cols-[minmax(0,1.65fr)_minmax(0,1fr)]"
            aria-label="Dashboard insights"
          >
            <div className="min-w-0 overflow-hidden">
              {charts}
            </div>

            <div className="min-w-0 overflow-hidden">
              {activity}
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}

export default DashboardLayout;

import * as React from 'react';
