      value: 51,
      secondaryValue: 45,
      annotation: 'Campaign launch',
    });

    expect(categoryDistributionData[0]).toMatchObject({
      id: 'enterprise',
      value: 38,
      percentage: 38,
    });

    expect(activityItems[0]).toMatchObject({
      id: 'act-001',
      status: 'completed',
      userName: 'Alicia Chen',
    });
  });

  it('marks only the overview navigation item as active and keeps ids unique', () => {
    const activeItems = navigationItems.filter((item) => item.isActive);
    expect(activeItems).toHaveLength(1);
    expect(activeItems[0]?.id).toBe('overview');

    const ids = navigationItems.map((item) => item.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

