describe('ChartsSection', () => {
  it('renders both chart cards and chart content when trend and category data are provided', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'steady' },
          { label: 'Tue', value: 14, secondaryValue: 6, annotation: 'up' },
        ]}
        categoryData={[
          { id: 'a', label: 'Alpha', value: 40, color: '#111111', percentage: 40, detail: 'Top segment' },
          { id: 'b', label: 'Beta', value: 60, color: '#222222', percentage: 60, detail: 'Growth segment' },
        ]}
      />,
    );

    expect(
      screen.getByRole('region', { name: 'Charts overview section' }),
    ).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();

    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();

    expect(
      screen.queryByText(/Trend data is unavailable right now/i),
    ).not.toBeInTheDocument();
    expect(
      screen.queryByText(/Category data is unavailable right now/i),
    ).not.toBeInTheDocument();
  });

  it('renders placeholder messages when both datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./i),
    ).toBeInTheDocument();
