    const { rerender } = render(<RecentActivity />);

    expect(screen.getByText('No recent activity')).toBeInTheDocument();
    expect(screen.queryByRole('list')).not.toBeInTheDocument();

    rerender(<RecentActivity items={[]} />);

    expect(screen.getByText('No recent activity')).toBeInTheDocument();
    expect(screen.queryByRole('list')).not.toBeInTheDocument();
