  it('sorts activities by newest timestamp first and renders core metadata', () => {
    render(
      <RecentActivity
        items={[
          {
            id: 'older',
            title: 'Older activity',
            description: 'Completed setup',
            status: 'completed',
            timestamp: '2024-01-02T09:00:00.000Z',
            category: 'Onboarding',
            userName: 'Taylor',
          },
          {
            id: 'newer',
            title: 'Newest activity',
            description: 'Created deployment',
            status: 'in-progress',
            timestamp: '2024-03-15T14:30:00.000Z',
            category: 'Release',
            userName: 'Jordan',
          },
        ]}
      />,
    );

    const list = screen.getByRole('list');
    const items = within(list).getAllByRole('listitem');

    expect(within(items[0]).getByRole('heading', { name: 'Newest activity' })).toBeInTheDocument();
    expect(within(items[0]).getByText('Created deployment')).toBeInTheDocument();
    expect(within(items[0]).getByText('in progress')).toBeInTheDocument();
    expect(within(items[0]).getByText('Release')).toBeInTheDocument();
    expect(within(items[0]).getByText('Jordan')).toBeInTheDocument();
    expect(within(items[0]).getByText(new Intl.DateTimeFormat(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    }).format(new Date('2024-03-15T14:30:00.000Z')))).toBeInTheDocument();

    expect(within(items[1]).getByRole('heading', { name: 'Older activity' })).toBeInTheDocument();
  });

  it('falls back for missing title/detail/time and pushes invalid timestamps to the end', () => {
    render(
      <RecentActivity
        items={[
          {
            id: 'invalid',
            title: '   ',
            status: 'needs-review',
            timestamp: 'not-a-date',
          },
          {
            id: 'valid',
            title: 'Valid activity',
            description: 'Has a valid timestamp',
            timestamp: '2024-02-01T10:00:00.000Z',
          },
          {
            id: 'missing-all',
          },
        ]}
      />,
    );

    const items = within(screen.getByRole('list')).getAllByRole('listitem');

    expect(within(items[0]).getByRole('heading', { name: 'Valid activity' })).toBeInTheDocument();

    expect(within(items[1]).getByRole('heading', { name: 'Untitled activity' })).toBeInTheDocument();
    expect(within(items[1]).getByText('Needs review')).toBeInTheDocument();
    expect(within(items[1]).getByText('needs review')).toBeInTheDocument();
    expect(within(items[1]).getByText('Time unavailable')).toBeInTheDocument();

    expect(within(items[2]).getByRole('heading', { name: 'Untitled activity' })).toBeInTheDocument();
    expect(within(items[2]).getByText('Status unavailable')).toBeInTheDocument();
    expect(within(items[2]).getByText('Time unavailable')).toBeInTheDocument();
  });
});

