import React from 'react';
import ReactDOM from 'react-dom/client';
import { act } from 'react-dom/test-utils';
import App from './App';
import { navigationItems } from './data/dashboardData';

function renderApp() {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = ReactDOM.createRoot(container);

  act(() => {
    root.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>,
    );
  });

  return {
    container,
    unmount: () => {
      act(() => {
        root.unmount();
      });
      container.remove();
    },
  };
}

describe('App', () => {
  afterEach(() => {
    document.body.innerHTML = '';
  });

  it('renders the initial dashboard view from the active navigation item', () => {
    const initialItem = navigationItems.find((item) => item.isActive && item.id.trim().length > 0);
    const expectedTitle = initialItem?.label ?? 'Dashboard';
    const expectedSubtitle = initialItem?.description ?? 'Operational insights for your team.';
    const expectedSupportInfo =
      'All dashboard data is rendered locally with no routing, background sync, or network requests.';

    const { container, unmount } = renderApp();

    expect(container.textContent).toContain(expectedTitle);
    expect(container.textContent).toContain(expectedSubtitle);
    expect(container.textContent).toContain(expectedSupportInfo);

    const activeButton = container.querySelector('button[aria-current="page"]');
    expect(activeButton?.textContent).toContain(expectedTitle);

    unmount();
  });

  it('updates the header and active navigation state when a valid navigation item is selected', () => {
    const { container, unmount } = renderApp();

    const analyticsButton = Array.from(container.querySelectorAll('button')).find((button) =>
      button.textContent?.includes('Analytics'),
    ) as HTMLButtonElement | undefined;

    expect(analyticsButton).toBeTruthy();

    act(() => {
      analyticsButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    expect(container.textContent).toContain('Analytics');
    expect(container.textContent).toContain('Performance trends and funnel insights');
    expect(analyticsButton?.getAttribute('aria-current')).toBe('page');
    expect(analyticsButton?.getAttribute('aria-pressed')).toBe('true');

    const previouslyActiveOverviewButton = Array.from(container.querySelectorAll('button')).find((button) =>
      button.textContent?.includes('Overview'),
    );
    expect(previouslyActiveOverviewButton?.getAttribute('aria-current')).toBeNull();

    unmount();
  });

  it('falls back to default header copy when a non-seeded navigation id is selected', () => {
    const { container, unmount } = renderApp();

    const sidebarButtons = Array.from(container.querySelectorAll('button'));
    const currentActiveButton = container.querySelector('button[aria-current="page"]');
    expect(currentActiveButton).toBeTruthy();

    act(() => {
      currentActiveButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    act(() => {
      sidebarButtons[0]?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    const appRootButton = container.querySelector('button[aria-current="page"]') as HTMLButtonElement | null;
    expect(appRootButton).toBeTruthy();

    act(() => {
      appRootButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    const appInstance = container.querySelector('aside');
    expect(appInstance).toBeTruthy();

    act(() => {
      const invalidSelectEvent = new CustomEvent('invalid-nav-test');
      container.dispatchEvent(invalidSelectEvent);
    });

    unmount();
  });
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { act } from 'react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { NavigationItem } from './data/dashboardData';
import { navigationItems } from './data/dashboardData';
import App from './App';

let latestSidebarProps:
  | {
      items: NavigationItem[];
      selectedItemId: string;
      onSelect: (itemId: string) => void;
    }
  | undefined;

vi.mock('./components/DashboardLayout', () => ({
  DashboardLayout: ({
    sidebar,
    header,
    metrics,
    charts,
    activity,
  }: {
    sidebar: React.ReactNode;
    header: React.ReactNode;
    metrics: React.ReactNode;
    charts: React.ReactNode;
    activity: React.ReactNode;
  }) => (
    <div>
      <div data-testid="sidebar">{sidebar}</div>
      <div data-testid="header">{header}</div>
      <div data-testid="metrics">{metrics}</div>
      <div data-testid="charts">{charts}</div>
      <div data-testid="activity">{activity}</div>
    </div>
  ),
}));

vi.mock('./components/Header', () => ({
  Header: ({ title, subtitle, supportInfo }: { title: string; subtitle: string; supportInfo: string }) => (
    <section>
      <h1>{title}</h1>
      <p>{subtitle}</p>
      <small>{supportInfo}</small>
    </section>
  ),
}));

vi.mock('./components/MetricCards', () => ({
  MetricCards: () => <div>metric-cards</div>,
}));

vi.mock('./components/ChartsSection', () => ({
  default: () => <div>charts-section</div>,
}));

vi.mock('./components/RecentActivity', () => ({
  default: () => <div>recent-activity</div>,
}));

vi.mock('./components/Sidebar', () => ({
  Sidebar: (props: {
    items: NavigationItem[];
    selectedItemId: string;
    onSelect: (itemId: string) => void;
  }) => {
    latestSidebarProps = props;

    return (
      <nav>
        {props.items.map((item) => (
          <button key={item.id} type="button" onClick={() => props.onSelect(item.id)}>
            {item.label}:{item.isActive ? 'active' : 'inactive'}
          </button>
        ))}
        <button type="button" onClick={() => props.onSelect('   ')}>
          whitespace-select
        </button>
        <button type="button" onClick={() => props.onSelect('unknown-nav-id')}>
          unknown-select
        </button>
      </nav>
    );
  },
}));

function renderApp() {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = ReactDOM.createRoot(container);

  act(() => {
    root.render(<App />);
  });

  return {
    container,
    unmount: () => {
      act(() => {
        root.unmount();
      });
      container.remove();
      latestSidebarProps = undefined;
    },
  };
}

describe('App', () => {
  afterEach(() => {
    document.body.innerHTML = '';
    latestSidebarProps = undefined;
  });

  it('renders the initial dashboard header from the seeded active navigation item', () => {
    const initialItem = navigationItems.find((item) => item.isActive && item.id.trim().length > 0);
    const expectedTitle = initialItem?.label ?? 'Dashboard';
    const expectedSubtitle = initialItem?.description ?? 'Operational insights for your team.';

    const { container, unmount } = renderApp();

    expect(container.textContent).toContain(expectedTitle);
    expect(container.textContent).toContain(expectedSubtitle);
    expect(container.textContent).toContain(
      'All dashboard data is rendered locally with no routing, background sync, or network requests.',
    );
    expect(container.textContent).toContain('metric-cards');
    expect(container.textContent).toContain('charts-section');
    expect(container.textContent).toContain('recent-activity');

    const activeItems = latestSidebarProps?.items.filter((item) => item.isActive);
    expect(latestSidebarProps?.selectedItemId).toBe(initialItem?.id);
    expect(activeItems).toHaveLength(1);
    expect(activeItems?.[0]?.id).toBe(initialItem?.id);

    unmount();
  });

  it('updates header copy and active navigation state when selecting a known item', () => {
    const { container, unmount } = renderApp();

    const analyticsButton = Array.from(container.querySelectorAll('button')).find((button) =>
      button.textContent?.includes('Analytics'),
    );

    act(() => {
      analyticsButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    expect(container.textContent).toContain('Analytics');
    expect(container.textContent).toContain('Performance trends and funnel insights');
    expect(latestSidebarProps?.selectedItemId).toBe('analytics');

    const activeItems = latestSidebarProps?.items.filter((item) => item.isActive) ?? [];
    expect(activeItems).toHaveLength(1);
    expect(activeItems[0]?.id).toBe('analytics');

    unmount();
  });

  it('ignores blank selections and falls back to default header copy for unknown ids', () => {
    const { container, unmount } = renderApp();

    const initialSelectedId = latestSidebarProps?.selectedItemId;

    const whitespaceButton = Array.from(container.querySelectorAll('button')).find((button) =>
      button.textContent?.includes('whitespace-select'),
    );

    act(() => {
      whitespaceButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    expect(latestSidebarProps?.selectedItemId).toBe(initialSelectedId);

    const unknownButton = Array.from(container.querySelectorAll('button')).find((button) =>
      button.textContent?.includes('unknown-select'),
    );

    act(() => {
      unknownButton?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });

    expect(latestSidebarProps?.selectedItemId).toBe('unknown-nav-id');
    expect(container.textContent).toContain('Dashboard');
    expect(container.textContent).toContain('Operational insights for your team.');

    const activeItems = latestSidebarProps?.items.filter((item) => item.isActive) ?? [];
    expect(activeItems).toHaveLength(1);
    expect(activeItems[0]?.id).toBe(navigationItems.find((item) => item.isActive)?.id);

    unmount();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const MAIN_MODULE_PATH = './main';

describe('src/main', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.unmock('./App');
    vi.unmock('react-dom/client');
    document.body.innerHTML = '';
  });

  afterEach(() => {
    document.body.innerHTML = '';
    vi.clearAllMocks();
  });

  it('creates a React root on #root and renders App inside StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const createRoot = vi.fn(() => ({ render }));

    vi.doMock('./App', () => ({
      default: () => <div data-testid="app">Mock App</div>,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    const React = await import('react');

    await import(MAIN_MODULE_PATH);

    const rootElement = document.getElementById('root');
    expect(createRoot).toHaveBeenCalledTimes(1);
    expect(createRoot).toHaveBeenCalledWith(rootElement);
    expect(render).toHaveBeenCalledTimes(1);

    const renderedTree = render.mock.calls[0][0];
    expect(renderedTree.type).toBe(React.StrictMode);
    expect(renderedTree.props.children.type).toBeTypeOf('function');
  });

  it('renders the App component as the child of StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const mockedApp = vi.fn(() => <div>Mock App</div>);

    vi.doMock('./App', () => ({
      default: mockedApp,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot: vi.fn(() => ({ render })),
    }));

    await import(MAIN_MODULE_PATH);

    const element = render.mock.calls[0][0];
    expect(element.props.children.type).toBe(mockedApp);
  });

  it('throws a clear error when the root element is missing', async () => {
    vi.doMock('./App', () => ({
      default: () => <div>Mock App</div>,
    }));

    const createRoot = vi.fn();
    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    await expect(import(MAIN_MODULE_PATH)).rejects.toThrow(
      'Root element with id "root" was not found.',
    );
    expect(createRoot).not.toHaveBeenCalled();
  });
});
